window.kbPageData["views/entry/k-4522b855176bbb2d"] = {"key":"entry/k-4522b855176bbb2d","state":{"route":"entry/k-4522b855176bbb2d"},"node":{"id":"k-4522b855176bbb2d","mode":"k","title":"中国特色现代企业制度建设目标","type":"制度与规则","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":["中国特色现代企业制度"],"qs":["政治理论必刷100题#46"],"current":true,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"tags":{"专题":["market"],"主类":["制度与规则"],"出处性质":["专项题解析","机构注释"],"学科":["政治理论","经济"],"来源主题":["产业、科技与对外开放"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"2025年《关于完善中国特色现代企业制度的意见》提出，经过5年左右，推动具备条件的企业普遍建立适合国情、符合实际、满足发展需要的中国特色现代企业制度。","review":{"definition":"2025年《关于完善中国特色现代企业制度的意见》提出，经过5年左右，推动具备条件的企业普遍建立适合国情、符合实际、满足发展需要的中国特色现代企业制度。","explanation":"这里的企业范围以“具备条件”为限定。B项将适用范围写成“所有国有企业”，同时把制度要求简化为“符合国情”。本题要求选出表述有误的一项，因此选B。","references":[],"evidence":"推动具备条件的\n\n企业普遍建立适合国情、符合实际、满足发展需要的中国特色现代企业制度","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"ac232bb3da2166c7","label":"中国特色现代企业制度","topic":"产业、科技与对外开放","category":"非时政","text":"3.中国特色现代企业制度\n党的十九届四中全会提出“深化国有企业改革，完善中国特色现代企业制度”，这是中\n央文件首次提出了“中国特色现代企业制度”的概念。习近平总书记指出“坚持党对国有企\n业的领导是重大政治原则，必须一以贯之；建立现代企业制度是国有企业的方向，也必须一\n以贯之。”现代企业制度定义为以市场经济为基础，以企业法人制度为主体，以公司制度\n为核心，以产权清晰、权责明确、政企分开、管理科学为条件的新型企业制度。“中国特\n色现代国有企业制度，‘特’就特在把党的领导融入公司治理各环节，把企业党组织内嵌到\n公司治理结构之中，明确和落实党组织在公司法人治理结构中的法定地位，做到组织落实、\n干部到位、职责明确、监督严格。”","source":{"doc":"6cbfb01fe723bba64b75","first":30,"last":30,"page":30,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#46":{"paper":"政治理论必刷100题","n":46,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",14],"asrc":["国省考政治理论必刷100题.pdf",60],"card":"0d22e74f10d21a4306d29542","links":[{"id":"k-4522b855176bbb2d","role":"直接考查","why":"考查五年左右建设目标的适用范围，判定依据是企业是否具备条件。"}]}},"terms":{},"references":{},"topics":[{"slug":"market","title":"统一大市场与公平竞争"}],"units":{"k-4522b855176bbb2d":[["政治理论必刷100题#46"]]}};
